using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _service;

    public OrderServiceTests()
    {
        _service = new OrderService();
    }

    #region CreateOrder

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithCorrectTotal()
    {
        // Arrange
        var items = new List<OrderItem>
        {
            new() { ProductName = "Widget", Price = 10m, Quantity = 2 },
            new() { ProductName = "Gadget", Price = 25m, Quantity = 1 },
        };

        // Act
        var order = _service.CreateOrder("cust-1", items);

        // Assert
        Assert.AreEqual(45m, order.Total);
        Assert.AreEqual("cust-1", order.CustomerId);
        Assert.IsNotNull(order.Id);
        Assert.HasCount(2, order.Items);
    }

    [TestMethod]
    public void CreateOrder_WithValidItems_StoresOrderForRetrieval()
    {
        // Arrange
        var items = new List<OrderItem>
        {
            new() { ProductName = "Widget", Price = 5m, Quantity = 3 },
        };

        // Act
        var created = _service.CreateOrder("cust-2", items);
        var retrieved = _service.GetOrder(created.Id);

        // Assert
        Assert.AreSame(created, retrieved);
    }

    [TestMethod]
    public void CreateOrder_WithNullCustomerId_ThrowsArgumentNullException()
    {
        var items = new List<OrderItem>
        {
            new() { ProductName = "Widget", Price = 10m, Quantity = 1 },
        };

        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _service.CreateOrder(null!, items));
        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithNullItems_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _service.CreateOrder("cust-1", null!));
        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithEmptyItems_ThrowsInvalidOperationException()
    {
        var ex = Assert.ThrowsExactly<InvalidOperationException>(
            () => _service.CreateOrder("cust-1", []));
        Assert.Contains("no items", ex.Message, StringComparison.OrdinalIgnoreCase);
    }

    [TestMethod]
    public void CreateOrder_SetsCreatedAtToRecentUtcTime()
    {
        // Arrange
        var before = DateTime.UtcNow;
        var items = new List<OrderItem>
        {
            new() { ProductName = "Clock", Price = 30m, Quantity = 1 },
        };

        // Act
        var order = _service.CreateOrder("cust-3", items);

        // Assert
        var after = DateTime.UtcNow;
        Assert.IsTrue(order.CreatedAt >= before && order.CreatedAt <= after);
    }

    #endregion

    #region GetOrder

    [TestMethod]
    public void GetOrder_WithNonExistentId_ReturnsNull()
    {
        var result = _service.GetOrder("non-existent-id");

        Assert.IsNull(result);
    }

    #endregion

    #region GetOrdersByCustomer

    [TestMethod]
    public void GetOrdersByCustomer_WithNoOrders_ReturnsEmptyList()
    {
        var result = _service.GetOrdersByCustomer("unknown-customer");

        Assert.IsEmpty(result);
    }

    [TestMethod]
    public void GetOrdersByCustomer_ReturnsOnlyMatchingOrders()
    {
        // Arrange
        var items = new List<OrderItem>
        {
            new() { ProductName = "Item", Price = 10m, Quantity = 1 },
        };
        _service.CreateOrder("customer-A", items);
        _service.CreateOrder("customer-A", items);
        _service.CreateOrder("customer-B", items);

        // Act
        var result = _service.GetOrdersByCustomer("customer-A");

        // Assert
        Assert.HasCount(2, result);
    }

    [TestMethod]
    public void GetOrdersByCustomer_SingleOrder_ReturnsSingleElement()
    {
        // Arrange
        var items = new List<OrderItem>
        {
            new() { ProductName = "Solo", Price = 99m, Quantity = 1 },
        };
        _service.CreateOrder("solo-customer", items);

        // Act
        var result = _service.GetOrdersByCustomer("solo-customer");

        // Assert
        var single = Assert.ContainsSingle(result);
        Assert.AreEqual(99m, single.Total);
    }

    #endregion

    #region DataRow - Total calculation scenarios

    [TestMethod]
    [DataRow(10, 1, 10, DisplayName = "Single item")]
    [DataRow(10, 3, 30, DisplayName = "Multiple quantity")]
    [DataRow(0, 5, 0, DisplayName = "Zero price")]
    public void CreateOrder_CalculatesCorrectTotal(int price, int quantity, int expectedTotal)
    {
        var items = new List<OrderItem>
        {
            new() { ProductName = "Test", Price = price, Quantity = quantity },
        };

        var order = _service.CreateOrder("cust", items);

        Assert.AreEqual((decimal)expectedTotal, order.Total);
    }

    #endregion
}

